if(additionalData?.midValue?.nvi_navigationPayload?.assignementList && additionalData?.midValue?.nvi_navigationPayload?.assignementList.length > 0){
   for (const entry of assignementList) {
    const entryNewRuleName = entry.ruleCode.id ?  entry.ruleCode.id : '';
    const entryCompanyName = entry.company.id ? entry.company.id : '';
    const entryOrgUnit = entry.orgUnit.id ? entry.orgUnit.id : '';
    const entryLocation = entry.location.id ? entry.location.id : '';
    const entryEmploymentType = entry.employmentType.id ? entry.employmentType.id : '';
    const entryContractType = entry.contractType.id ? entry.contractType.id : '';
    const entryEmployee = entry.employee.id ? entry.employee.id : ' ';
    const entryValidFrom = new Date(entry.activeFrom);
    const entryValidTo = new Date(entry.activeTo);

    const isMatchingRuleName = entryNewRuleName === newRuleName;
    const isMatchingCompany = entryCompanyName === newCompanyName;
    const isMatchingOrgUnit = entryOrgUnit === newOrgUnit;
    const isMatchingLocation = entryLocation === newLocation;
    const isMatchingEmploymentType = entryEmploymentType === newEmploymentType;
    const isMatchingContractType = entryContractType === newContractType;
    const isMatchingEmployee = entryEmployee === newEmployee

    if (entry.id === currentEntryId) {
        continue;
    }

    const isOverlapping = (newValidFrom <= entryValidTo && newValidTo >= entryValidFrom);

    if (isMatchingRuleName && isOverlapping && isMatchingCompany && isMatchingOrgUnit && isMatchingLocation && isMatchingEmploymentType && isMatchingContractType && isMatchingEmployee) {

        overlapingPeriodState.setValue(true);
        return true;  
    }
}
